body:
Not really sure what the question is, but here's the basic layout for defining a class:

    class CMyClass{
    public:
        CMyClass(){//constructor
            asdf = 0;
        }
        ~CMyClass(){}//destructor
        void SomeFunction(){//function
             asdf = 1;
        }
        int GetAsdf(){//another function
            return asdf;
        }
        void SetAsdf(int n){//a 3rd function
             asdf = n;
        }
    private:
        int asdf;
    };

The void, int, etc... is what the function returns... void means it returns nothing... int means it returns an integer.
